package com.privatezero.stadiumpad;
import android.content.*;import android.media.midi.*;import android.os.*;import java.io.*;import java.util.*;import static com.privatezero.stadiumpad.Data.*;
/** App-scoped USB MIDI, bound to a user-confirmed physical Stadium and native device identity. */
final class MatrixUSB implements Closeable {
 final Context context;final MidiManager manager;final Handler main=new Handler(Looper.getMainLooper());final Runnable changed;MidiDevice device;MidiInputPort port;String serial="",name="";int deviceID=-1,epoch=0;boolean opening=false;final MidiManager.DeviceCallback callback;
 MatrixUSB(Context context,Runnable changed){this.context=context;this.changed=changed;manager=(MidiManager)context.getSystemService(Context.MIDI_SERVICE);callback=new MidiManager.DeviceCallback(){public void onDeviceAdded(MidiDeviceInfo info){refresh();}public void onDeviceRemoved(MidiDeviceInfo info){refresh();}public void onDeviceStatusChanged(MidiDeviceStatus status){refresh();}};if(manager!=null)manager.registerDeviceCallback(callback,main);refresh();}
 List<MidiDeviceInfo> candidates(){List<MidiDeviceInfo> result=new ArrayList<>();if(manager!=null)for(MidiDeviceInfo info:manager.getDevices()){String label=(info.getProperties().getString(MidiDeviceInfo.PROPERTY_NAME,"")+" "+info.getProperties().getString(MidiDeviceInfo.PROPERTY_PRODUCT,"")).toLowerCase(Locale.ROOT);String serial=info.getProperties().getString(MidiDeviceInfo.PROPERTY_SERIAL_NUMBER,"");if(info.getType()==MidiDeviceInfo.TYPE_USB&&info.getInputPortCount()==1&&label.contains("helix stadium")&&!serial.isEmpty())result.add(info);}return result;}
 synchronized void refresh(){List<MidiDeviceInfo> matches=candidates();if(matches.size()!=1){release();changed.run();return;}MidiDeviceInfo info=matches.get(0);String next=info.getProperties().getString(MidiDeviceInfo.PROPERTY_SERIAL_NUMBER,"");if(deviceID==info.getId()&&serial.equals(next)&&(port!=null||opening))return;release();deviceID=info.getId();serial=next;name=info.getProperties().getString(MidiDeviceInfo.PROPERTY_NAME,"Helix Stadium USB");opening=true;int token=epoch;manager.openDevice(info,opened->{synchronized(MatrixUSB.this){if(token!=epoch||opened==null){if(opened!=null)try{opened.close();}catch(Exception ignored){}opening=false;changed.run();return;}device=opened;port=opened.openInputPort(0);opening=false;if(port==null)release();changed.run();}},main);}
 synchronized void release(){epoch++;try{if(port!=null)port.close();}catch(Exception ignored){}try{if(device!=null)device.close();}catch(Exception ignored){}port=null;device=null;deviceID=-1;serial="";opening=false;}
 String binding(String identity){return "MatrixUSBPair."+identity;}
 synchronized boolean bound(String identity){try{return port!=null&&!identity.isEmpty()&&hash(serial.getBytes("UTF-8")).equals(context.getSharedPreferences("StadiumPad",0).getString(binding(identity),""));}catch(Exception e){return false;}}
 synchronized void bind(String identity)throws Exception{refresh();require(port!=null&&!identity.isEmpty(),"Connect one Stadium USB MIDI device and wait for it to open");context.getSharedPreferences("StadiumPad",0).edit().putString(binding(identity),hash(serial.getBytes("UTF-8"))).apply();changed.run();}
 synchronized void send(String identity,String kind,int output,int source,int field,int value,int channel)throws Exception{refresh();require(bound(identity)&&channel>=1&&channel<=16,"Confirmed USB Stadium disconnected or changed; nothing sent");int cc=kind.equals("panel")?9:kind.equals("clearSolos")?103:Matrix.cc(source,field);int v=kind.equals("panel")?output+6:kind.equals("clearSolos")?127:value;byte[] press={(byte)(0xb0+channel-1),(byte)cc,(byte)v};port.send(press,0,press.length);if(kind.equals("clearSolos")||kind.equals("strip")&&field==3){byte[] release={press[0],press[1],0};port.send(release,0,release.length);}}
 public synchronized void close(){if(manager!=null)manager.unregisterDeviceCallback(callback);release();}
}
